export function Drawer({ open, title, sub, onClose, children, footer }:
 { open: boolean; title: string; sub?: string; onClose: () => void;
 children?: React.ReactNode; footer?: React.ReactNode; }) {
 React.useEffect(() => {
 const h = (e: KeyboardEvent) => e.key === "Escape" && onClose();
 if (open) window.addEventListener("keydown", h);
 return () => window.removeEventListener("keydown", h);
 }, [open, onClose]);
 if (!open) return null;
 return (
 <>
 <div className="ci-drawer-overlay" onClick={onClose} />
 <aside className="ci-drawer" role="dialog" aria-label={title}>
 <header className="ci-drawer__head">
 <div>
 <h3 style={{ margin: 0, fontSize: 16, fontWeight: 700 }}>{title}</h3>
 {sub && <p className="ci-panel__sub" style={{ marginTop: 4 }}>{sub}</p>}
 </div>
 <button className="ci-drawer__close" onClick={onClose} aria-label="Close">
 <Icon.x style={{ width: 15, height: 15 }} />
 </button>
 </header>
 <div className="ci-drawer__body">{children}</div>
 {footer && <div className="ci-drawer__foot">{footer}</div>}
 </aside>
 </>
 );
}

