 <Panel hover title={`${rows.length} athletes`} sub="Click a row to open the profile drawer"
 right={
 <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
 <div className="ci-search" style={{ minWidth: 200, padding: "6px 12px" }}>
 <input placeholder="Search name…" value={q} onChange={e => setQ(e.target.value)} aria-label="Search athletes" />
 </div>
 <div className="ci-seg">
 {SEGMENTS.map(s => (
 <button key={s} className={`ci-seg__btn ${seg === s ? "ci-seg__btn--active" : ""}`} onClick={() => setSeg(s)}>{s}</button>
 ))}
 </div>
 </div>
 }>
 <AthleteTable rows={rows} onSelect={onAthlete} />
 </Panel>
 </div>
 );
}
